// PhaseDiffFromActs computes the phase-wise difference in the
// activity state between the minus [ActM] and plus [ActP] phases,
// measured using 1 minus the correlation (centered cosine aka
// normalized dot product). 0 = no difference, 2 = maximum difference.
func (ly *LayerParams) PhaseDiffFromActs(ctx *Context) {
	li := ly.Index
	for di := uint32(0); di < ctx.NData; di++ {
		lpi := ly.PoolIndex(0)
		avgM := PoolAvgMax(AMAct, AMMinus, Avg, lpi, di)
		avgP := PoolAvgMax(AMAct, AMPlus, Avg, lpi, di)
		cosv := float32(0)
		ssm := float32(0)
		ssp := float32(0)
		nn := ly.Indexes.NNeurons
		for lni := uint32(0); lni < nn; lni++ {
			ni := ly.Indexes.NeurSt + lni
			if NeuronIsOff(ni) {
				continue
			}
			ap := Neurons.Value3D(int(ni), int(di), int(ActP)) - avgP // zero mean = correl
			am := Neurons.Value3D(int(ni), int(di), int(ActM)) - avgM
			cosv += ap * am
			ssm += am * am
			ssp += ap * ap
		}
		dist := math32.Sqrt(ssm * ssp)
		if dist != 0 {
			cosv /= dist
		}
		LayerStates.Set3D(1-cosv, int(li), int(di), int(LayerPhaseDiff))
		avg := LayerStates.Value3D(int(li), int(di), int(LayerPhaseDiffAvg))
		vr := LayerStates.Value3D(int(li), int(di), int(LayerPhaseDiffVar))
		ly.Acts.Dt.AvgVarUpdate(&avg, &vr, 1-cosv)
		LayerStates.Set3D(avg, int(li), int(di), int(LayerPhaseDiffAvg))
		LayerStates.Set3D(vr, int(li), int(di), int(LayerPhaseDiffVar))
	}
}

// Correlation computes the correlation (-1, 1) between any two
// neuron variables. Correlation is the (centered cosine aka
// normalized dot product). The ctr flag can be used to
// compute cosine instead of correlation (ctr = false).
func (ly *LayerParams) Correlation(ctx *Context, di uint32, aVar, bVar NeuronVars, center bool) float32 {
	avgA := float32(0)
	avgB := float32(0)
	nn := ly.Indexes.NNeurons
	if center {
		nact := 0
		for lni := uint32(0); lni < nn; lni++ {
			ni := ly.Indexes.NeurSt + lni
			if NeuronIsOff(ni) {
				continue
			}
			avgA += Neurons.Value3D(int(ni), int(di), int(aVar))
			avgB += Neurons.Value3D(int(ni), int(di), int(bVar))
			nact++
		}
		if nact > 0 {
			avgA /= float32(nact)
			avgB /= float32(nact)
		}
	}
	cosv := float32(0)
	ssa := float32(0)
	ssb := float32(0)
	for lni := uint32(0); lni < nn; lni++ {
		ni := ly.Indexes.NeurSt + lni
		if NeuronIsOff(ni) {
			continue
		}
		a := Neurons.Value3D(int(ni), int(di), int(aVar)) - avgA
		b := Neurons.Value3D(int(ni), int(di), int(bVar)) - avgB
		cosv += a * b
		ssa += a * a
		ssb += b * b
	}
	dist := math32.Sqrt(ssa * ssb)
	if dist != 0 {
		cosv /= dist
	}
	return cosv
}

